mapper.select:
SELECT DISTINCT
       a.id AS "id",
       a.name AS "name",
       a.person_type AS "personType",
       a.gender AS "gender",
        jso.office_name AS "company",
        pa.position_name AS "department",
        pl.prod_line_name AS "prodLine",
        wg.work_group_name AS "team",
        a.job_type AS "jobType",
       a.safety_helmet_id AS "safetyHelmetId",
       a.personnel_status AS "personnelStatus",
       a.safety_education AS "safetyEducation",
       a.identity_card AS "identityCard",
       a.phone_number AS "phoneNumber",
       a.helmet_returned AS "helmetReturned",
       a.departure_type AS "departureType",
       a.departure_reason AS "departureReason",
       a.departure_date AS "departureDate",
       a.is_external_personnel AS "isExternalPersonnel",
       a.create_by AS "createBy",
       a.create_date AS "createDate",
       a.update_by AS "updateBy",
       a.update_date AS "updateDate",
       a.remarks AS "remarks",
       a.status AS "status",
       a.dept ,
       a.position
FROM ${sqlMap.table.toSql()}
LEFT JOIN fms_position_archive pa ON a.department = pa.id COLLATE utf8mb4_general_ci
LEFT JOIN fms_prod_line pl ON a.prod_line = pl.id COLLATE utf8mb4_general_ci
LEFT JOIN fms_work_group wg ON a.team = wg.id COLLATE utf8mb4_general_ci
LEFT JOIN swm_work_type backup_wt ON a.job_type = backup_wt.work_type_code COLLATE utf8mb4_general_ci
LEFT JOIN js_sys_office jso ON a.company = jso.office_code COLLATE utf8mb4_general_ci
LEFT JOIN fms_worker f ON a.identity_card = f.identity_code COLLATE utf8mb4_general_ci

    a.status = '0' and a.personnel_status = '1'

        AND jso.office_name LIKE CONCAT('%', #{company}, '%')


        AND a.id = #{id}


        AND  pa.position_name = #{department}


        AND pl.prod_line_name = #{prodLine}


        AND wg.work_group_name = #{team}


        AND a.job_type = #{jobType}




        AND a.name LIKE CONCAT('%', #{name}, '%')


        AND a.identity_card LIKE CONCAT('%', #{identityCard}, '%')


        AND a.phone_number LIKE CONCAT('%', #{phoneNumber}, '%')


        AND a.personnel_status = #{personnelStatus}


        AND a.status = #{status}


        AND a.person_type = #{personType}


        AND a.gender = #{gender}


        AND a.safety_helmet_id = #{safetyHelmetId}


        AND a.safety_education = #{safetyEducation}


        AND a.helmet_returned = #{helmetReturned}


        AND a.departure_type = #{departureType}


        AND a.is_external_personnel = #{isExternalPersonnel}






            AND a.identity_card IN

                #{id}




            AND a.identity_card NOT IN

                #{id}




ORDER BY ${sqlMap.order.toSql()}

SELECT a.id AS "id", a.name AS "name", a.person_type AS "personType", a.gender AS "gender", jso.office_name AS "company", pa.position_name AS "department", pl.prod_line_name AS "prodLine", wg.work_group_name AS "team", a.job_type AS "jobType", a.safety_helmet_id AS "safetyHelmetId", a.personnel_status AS "personnelStatus", a.identity_card AS "identityCard", a.phone_number AS "phoneNumber", a.create_by AS "createBy", a.create_date AS "createDate", a.update_by AS "updateBy", a.update_date AS "updateDate", a.remarks AS "remarks", a.status AS "status" FROM swm_person a left join fms_position_archive pa on a.department = pa.id COLLATE utf8mb4_general_ci left join fms_prod_line pl on a.prod_line = pl.id COLLATE utf8mb4_general_ci left join fms_work_group wg on a.team = wg.id COLLATE utf8mb4_general_ci LEFT JOIN swm_work_type backup_wt ON a.job_type = backup_wt.work_type_code COLLATE utf8mb4_general_ci left join js_sys_office jso on a.company = jso.office_code COLLATE utf8mb4_general_ci WHERE a.personnel_status = '1' AND a.status = '0'
AND a.company = #{query.officeCode}
AND a.department = #{query.positionArchiveId}
AND a.prod_line = #{query.prodLineId}
AND a.team = #{query.workGroupId}
AND a.job_type = #{query.jobType}
GROUP BY a.id ORDER BY MAX(a.update_date) DESC

SELECT sp.`name`, sp.gender, sp.phone_number, sp.person_type FROM swm_daily_attendance sda join swm_person sp on sda.identity_card = sp.identity_card
sda.`status` = '0' and sp.`status` ='0' and sp.personnel_status = '1' and sda.clock_in_date is not NULL and sda.attendance_date = #{date}
and sp.person_type in
#{personType}

SELECT DISTINCT a.id AS "id", a.NAME AS "name", a.person_type AS "personType", a.gender AS "gender", a.corp_name AS "company", a.job_type AS "jobType", a.safety_helmet_id AS "safetyHelmetId", a.personnel_status AS "personnelStatus", a.safety_education AS "safetyEducation", a.identity_card AS "identityCard", a.phone_number AS "phoneNumber", a.helmet_returned AS "helmetReturned", a.departure_type AS "departureType", a.departure_reason AS "departureReason", a.departure_date AS "departureDate", a.is_external_personnel AS "isExternalPersonnel", a.create_by AS "createBy", a.create_date AS "createDate", a.update_by AS "updateBy", a.update_date AS "updateDate", a.remarks AS "remarks", a.STATUS AS "status", a.dept, a.position FROM ${sqlMap.table.toSql()}
a.status = '0'
AND a.personnel_status = #{personnelStatus}
AND a.status = #{status}
AND #{random} = #{random}
ORDER BY ${sqlMap.order.toSql()}
